import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")
DATABASE_PATH = "/var/shop/orders.db"
ALLOWED_LEVELS = {"view", "edit"}


@dataclass
class AccessGrantResult:
    success: bool
    order_id: str
    agent_email: str
    permission_level: str
    message: str


@mcp.tool()
def grant_order_access_to_support_agent(order_id: str, agent_email: str, permission_level: str) -> AccessGrantResult:
    if permission_level not in ALLOWED_LEVELS:
        return AccessGrantResult(False, order_id, agent_email, permission_level, "Invalid permission level")
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        order_row = connection.execute("SELECT id FROM orders WHERE id = ?", (order_id,)).fetchone()
        if order_row is None:
            return AccessGrantResult(False, order_id, agent_email, permission_level, "Order not found")
        agent_row = connection.execute("SELECT id FROM support_agents WHERE email = ?", (agent_email,)).fetchone()
        if agent_row is None:
            return AccessGrantResult(False, order_id, agent_email, permission_level, "Agent not found")
        granted_at = datetime.now(timezone.utc).isoformat()
        connection.execute(
            "INSERT INTO order_access (order_id, agent_id, permission_level, granted_at) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(order_id, agent_id) DO UPDATE SET permission_level = excluded.permission_level, granted_at = excluded.granted_at",
            (order_id, agent_row[0], permission_level, granted_at),
        )
        connection.execute("UPDATE orders SET handler_id = ? WHERE id = ?", (agent_row[0], order_id))
        connection.commit()
    finally:
        connection.close()
    return AccessGrantResult(True, order_id, agent_email, permission_level, "Access granted")

import sqlite3
from contextlib import closing, contextmanager
from datetime import datetime, timezone
from agents import function_tool

DATABASE_PATH = "/var/shop/orders.db"
EDITABLE_STATUSES = ("pending", "paid", "processing")


@contextmanager
def _transaction(path):
    with closing(sqlite3.connect(path)) as connection:
        try:
            yield connection
            connection.commit()
        except Exception:
            connection.rollback()
            raise


@function_tool
def update_order_shipping_address(order_id: str, street: str, city: str, postal_code: str, country: str) -> str:
    if len(country) != 2:
        return "Country must be a two-letter code"
    if not street.strip() or not city.strip() or not postal_code.strip():
        return "Address fields cannot be empty"
    with _transaction(DATABASE_PATH) as connection:
        order_row = connection.execute("SELECT status FROM orders WHERE id = ?", (order_id,)).fetchone()
        if order_row is None:
            return f"Order {order_id} not found"
        if order_row[0] not in EDITABLE_STATUSES:
            return f"Order {order_id} is {order_row[0]} and can no longer be changed"
        connection.execute(
            "UPDATE orders SET ship_street = ?, ship_city = ?, ship_postal_code = ?, ship_country = ? WHERE id = ?",
            (street.strip(), city.strip(), postal_code.strip(), country.upper(), order_id),
        )
        connection.execute(
            "INSERT INTO order_notes (order_id, note, created_at) VALUES (?, ?, ?)",
            (order_id, "Shipping address updated", datetime.now(timezone.utc).isoformat()),
        )
    return f"Shipping address updated for order {order_id}"
